from __future__ import annotations
from .canonical import digest_object, stable_id
from .constants import CLAIM_CEILING, GENERATED_TIME_SEMANTICS, MASTER_PHASE, OWNER, PHASE_ID, PRODUCER, REVIEWER, SCHEMA_VERSION

def build_handoff(source_digests:list[str], output_digest:str, counts:dict, blocker_ids:list[str]) -> dict:
    value={
      "schema_version":SCHEMA_VERSION,"handoff_type":"LCM11A_TO_LCM11B","handoff_id":stable_id("LCM11AHANDOFF",output_digest,*blocker_ids),"phase_id":PHASE_ID,"master_phase":MASTER_PHASE,"claim_ceiling":CLAIM_CEILING,"producer":PRODUCER,"owner":OWNER,"reviewer":REVIEWER,"generated_at":None,"generated_time_semantics":GENERATED_TIME_SEMANTICS,"deterministic_identity":True,"source_digests":source_digests,"output_manifest_digest":output_digest,"counts":counts,"completed_gates":["VISUAL_OBJECT_INVENTORY","DETERMINISTIC_NAMESPACE_CONTRACTS","ANCHOR_CONTRACTS_OR_BLOCKERS","LIFECYCLE_CONTRACTS_OR_BLOCKERS","MULTI_INSTANCE_COLLISION_SIMULATION","SOURCE_EVENT_BINDINGS_OR_BLOCKERS","AUTHORITY_NEGATIVE_BOUNDARY"],"failed_dimensions":[],"blocked_dimensions":["LEGACY_COLLISION_REMEDIATION","MISSING_OWNED_CLEANUP_REMEDIATION","CURRENT_BAR_ANCHOR_REMEDIATION"] if blocker_ids else [],"unknown_dimensions":["HUMAN_OWNER_APPROVAL","METAEDITOR_RUNTIME_MATRIX","LIVE_CHART_RESTART_EVIDENCE"],"allowed_next_actions":["IMPLEMENT_CANONICAL_VISUALIZERS","APPLY_INSTANCE_AND_CHART_ISOLATION","BUILD_GOLDEN_VISUAL_FIXTURES","RUN_VISUAL_PARITY","PREPARE_BOUNDED_VISUAL_CONSUMER_CUTOVER"],"forbidden_actions":["DOMAIN_STATE_MUTATION_FROM_VISUALIZER","ORDER_SUBMISSION","CAPITAL_ACTIVATION","BROAD_SOURCE_DELETE","LEGACY_SOURCE_DELETE","UNSCOPED_OBJECT_CLEANUP","UNKNOWN_WAIVER"],"runtime_authority_created":False,"live_order_authority_created":False,"capital_authority_created":False,"consumer_cutover_allowed":False,"validation_status":"PASS"}
    value["handoff_digest"]=digest_object(value,"handoff_digest"); return value
